'use strict';
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const E=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let session={}, data=null, page='overview', nativeData=null, query='', activeJob=null, pendingPlan=null, refreshBusy=false, credentialsBusy=false, activeDevice=null;
const pages={overview:'Системный монитор',exit:'Выход в интернет',peers:'Клиенты',routes:'Подсети и DNS',native:'Подключение Keenetic',diagnostics:'Диагностика',logs:'Журналы',backups:'Резервные копии',system:'Клиент и панель'};
const labels={accept_dns:'Принимать DNS с сервера',accept_routes:'Принимать маршруты подсетей',allow_lan:'Доступ к своей LAN при использовании внешнего Exit node',shields_up:'Блокировать входящие подключения',ssh:'Tailscale SSH',webclient:'Встроенный веб-клиент',snat:'SNAT подсетей',stateful:'Фильтрация соединений'};
async function api(url,body){
 const opt={headers:{},credentials:'same-origin',signal:AbortSignal.timeout(45000)};
 if(body!==undefined){opt.method='POST';opt.headers={'Content-Type':'application/json','X-CSRF-Token':session.csrf||''};opt.body=JSON.stringify(body)}
 let r;try{r=await fetch(url,opt)}catch(error){if(['AbortError','TimeoutError'].includes(error.name))throw Error('Роутер не ответил вовремя. Проверьте состояние операции перед повтором.');throw Error('Нет связи с панелью. Проверьте подключение к роутеру.')}
 let d;try{d=await r.json()}catch{throw Error('Роутер вернул неполный ответ. Проверьте соединение.')}
 if(!r.ok){if(r.status===401&&!url.endsWith('/login')&&!credentialsBusy&&session.authenticated){session.authenticated=false;void boot()}throw Error(d.error||'Не удалось выполнить запрос')}
 return d
}
function toast(text,bad=false){const p=document.createElement('div');p.className='toast'+(bad?' bad':'');p.textContent=text;$('#toasts').append(p);setTimeout(()=>p.remove(),6500)}
function date(t){return t?new Date(t*1000).toLocaleString('ru-RU',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'}):'—'}
function bytes(n){n=Number(n)||0;const a=['Б','КБ','МБ','ГБ','ТБ'];let i=0;while(n>=1000&&i<4){n/=1000;i++}return n.toLocaleString('ru-RU',{maximumSignificantDigits:3})+' '+a[i]}
function duration(n){return Math.floor(n/86400)+' д '+Math.floor(n%86400/3600)+' ч'}
function stateLabel(s){return {Running:'Подключён',Stopped:'Отключён',NeedsLogin:'Нужен вход',NeedsMachineAuth:'Нужно одобрение',Starting:'Подключение',NoState:'Не настроен',Unavailable:'Недоступен'}[s]||s}
function status(){const s=data.tailscale;const good=s.backend_state==='Running'&&s.online;$('#live-state').textContent=stateLabel(s.backend_state);$('#live-state').className='status-badge '+(good?'good':'warn');$('#sidebar-status').textContent=stateLabel(s.backend_state);$('#sidebar-dot').className='live-dot'+(good?'':' off');$('#panel-version').textContent='v'+data.panel_version;$('#last-update').textContent='Обновлено '+new Date().toLocaleTimeString('ru-RU');}
function intro(title,description,buttons=''){return `<div class="page-intro"><div><h1>${E(title)}</h1><p>${E(description)}</p></div>${buttons?`<div class="actions">${buttons}</div>`:''}</div>`}
function check(key,title,description,value){return `<label class="check-row"><span>${E(title)}<small>${E(description)}</small></span><input type="checkbox" name="${E(key)}" ${value?'checked':''}></label>`}
function pairs(items){return '<dl class="definition">'+items.map(([k,v])=>`<dt>${E(k)}</dt><dd>${v}</dd>`).join('')+'</dl>'}
function address(n){return (n?.TailscaleIPs||[]).find(x=>!x.includes(':'))||(n?.TailscaleIPs||[])[0]||'—'}
function selectedExit(){const s=data.tailscale;return s.peers.find(n=>n.ID===s.prefs.ExitNodeID)}
function goodBadge(online){return `<span class="state-dot ${online?'online':''}"></span>${online?'В сети':'Не в сети'}`}
function health(){return data.tailscale.health.map(x=>`<div class="alert">${E(x)}</div>`).join('')}
function jobRows(){return (data.jobs||[]).slice(0,5).map(j=>`<li><button class="job-link" data-job="${E(j.id)}">${E(j.label)}</button><span class="muted">${j.state==='done'?'Готово':j.state==='error'?'Ошибка':j.state==='interrupted'?'Прервано':'Выполняется'}</span></li>`).join('')||'<li class="muted">Операций пока нет</li>'}
function addressCell(peer){
 const ip=address(peer);if(!ip||ip==='—')return E(ip||'—');
 return `<span class="address-line"><span>${E(ip)}</span><button type="button" class="copy-address" data-copy-address="${E(ip)}" aria-label="Скопировать IP-адрес ${E(ip)}" title="Скопировать IP-адрес">${icon('copy')}</button></span>`
}
function legacyCopyAddress(text,button){
 const node=button.previousElementSibling,selection=window.getSelection();
 if(!node||node.textContent!==text||!selection)throw Error('Clipboard unavailable');
 const range=document.createRange();range.selectNodeContents(node);selection.removeAllRanges();selection.addRange(range);
 if(!document.execCommand('copy'))throw Error('Clipboard unavailable')
}
async function copyAddress(text,button){
 try{
  if(window.isSecureContext&&navigator.clipboard?.writeText){button.disabled=true;try{await navigator.clipboard.writeText(text)}catch{button.disabled=false;legacyCopyAddress(text,button)}}
  else legacyCopyAddress(text,button);
  toast('IP-адрес скопирован')
 }catch{toast('Не удалось скопировать. Выделите IP-адрес и нажмите Ctrl+C.',true)}
 finally{button.disabled=false}
}

function peerTable(peers,short=false){return `<div class="table-wrap"><table class="table"><thead><tr><th>Клиент</th><th>Адрес Tailscale</th><th>Состояние</th>${short?'':'<th>Соединение</th><th>Трафик</th>'}<th>Управление</th></tr></thead><tbody>${peers.map(n=>{const card=data.devices?.[n.ID]||{},url=deviceURL(n,card);return `<tr><td><span class="peer-name">${E(n.HostName||n.DNSName||'Устройство')}<small>${n.is_self?'Этот роутер':E(n.OS||'—')}${n.ExitNodeOption?' · Exit node':''}</small></span>${card.notes?`<span class="peer-note">${E(card.notes.slice(0,85))}${card.notes.length>85?'…':''}</span>`:''}</td><td class="ip">${addressCell(n)}</td><td>${goodBadge(n.Online)}</td>${short?'':`<td>${n.is_self?'Локально':n.CurAddr?'Прямое':n.Relay?'Через DERP':'—'}</td><td class="peer-traffic"><span aria-label="Получено ${bytes(n.RxBytes)}"><span class="traffic-direction" aria-hidden="true">↓</span>${bytes(n.RxBytes)}</span><span aria-label="Отправлено ${bytes(n.TxBytes)}"><span class="traffic-direction" aria-hidden="true">↑</span>${bytes(n.TxBytes)}</span></td>`}<td><div class="peer-actions">${url?`<a class="button" href="${E(url)}" target="_blank" rel="noopener noreferrer" aria-label="Веб-интерфейс ${E(n.HostName||'устройства')}" title="${n.is_self&&!card.custom_url?'Панель этого роутера':'Требуется доступ к устройству; доступность порта не проверена'}">${icon('external')} ${n.is_self&&!card.custom_url?'Панель':'Веб'}</a>`:''}<button class="text-link" data-device="${E(n.ID)}" aria-label="Карточка ${E(n.HostName||'устройства')}">${icon('edit')}</button>${n.is_self?'':`<button class="text-link" data-ping="${E(address(n))}" aria-label="Проверить ${E(n.HostName||'устройство')}">${icon('pulse')}</button>`}</div></td></tr>`}).join('')}</tbody></table>${peers.length?'':'<div class="empty">В этой сети пока нет доступных клиентов.</div>'}</div>`}
function authLink(){const url=data.tailscale.auth_url;if(!url||!/^https:\/\//.test(url))return '';return `<div class="note warn">Подтвердите вход в браузере: <a href="${E(url)}" target="_blank" rel="noopener noreferrer">Открыть страницу регистрации</a></div>`}
function overview(){const s=data.tailscale,p=s.prefs,exit=selectedExit(),own=s.self;return intro('Системный монитор','Tailscale на роутере: устройства, защищённые маршруты и выход в интернет.',`<button data-action="${s.backend_state==='Running'?'disconnect':'resume'}">${s.backend_state==='Running'?'Отключить':'Подключить'}</button><button data-action="restart" class="quiet">Перезапустить</button>`)+health()+authLink()+`<div class="split"><section class="surface"><div class="network-head"><div class="identity">${E(own.HostName||p.Hostname||'Роутер')}<small>${E(own.DNSName||'Узел Keenetic / Netcraze')}</small></div><span class="status-badge ${s.online?'good':'warn'}">${stateLabel(s.backend_state)}</span></div><div class="network-path"><div class="path-node"><strong>Ваш роутер</strong><small>${E(address(own))}</small></div><span class="path-connector">⟷</span><div class="path-node"><strong>${exit?E(exit.HostName):'Сеть Tailscale'}</strong><small>${exit?'Выход через Exit node':(s.peers.filter(n=>n.Online).length+' устройств в сети')}</small></div><span class="path-connector">⟷</span><div class="path-node"><strong>${exit?'Интернет':'Другие устройства'}</strong><small>${exit?'Защищённый выход':'Прямые связи / DERP'}</small></div></div>${pairs([['Сервер управления',E(p.ControlURL||'—')],['Выходной узел',exit?`<a href="#exit">${E(exit.HostName)}</a>`:'<a href="#exit">Не используется</a>'],['Адрес IPv6',E((own.TailscaleIPs||[]).find(x=>x.includes(':'))||'—')],['Версия клиента',E(s.version.split('-')[0]||'Не установлен')]])}<div class="stat-row"><div><strong>${s.peers.filter(n=>n.Online).length}<span> / ${s.peers.length}</span></strong><span>Устройств в сети</span></div><div><strong>${bytes(data.metrics?.rx_bytes)}</strong><span>Получено</span></div><div><strong>${bytes(data.metrics?.tx_bytes)}</strong><span>Отправлено</span></div></div></section><div class="stack"><section class="surface"><h2>Состояние роутера</h2>${pairs([['Работает',E(duration(data.system.uptime))],['Интерфейс',E(data.config.tun)],['Архитектура',E(data.system.architecture)],['Подсети',E((p.AdvertiseRoutes||[]).filter(x=>!x.endsWith('/0')).length)],['Выход через роутер',s.exit_advertised?'Объявлен в сети':'Выключен']])}<p class="muted small">Одобрение маршрутов и Exit node задаётся на сервере вашей сети.</p><a href="#native">Подключение в Keenetic</a></section><section class="surface"><h2>Последние операции</h2><ul class="job-list">${jobRows()}</ul></section></div></div><section class="surface"><div class="section-heading"><h2>Клиенты в сети</h2><a href="#peers">Все клиенты</a></div>${peerTable(s.peers.filter(n=>n.Online).slice(0,5),true)}</section>`}
function exitView(){const s=data.tailscale,p=s.prefs,selected=selectedExit(),nodes=s.peers.filter(n=>n.ExitNodeOption);return intro('Выход в интернет','Настройка внешнего Exit node и раздачи интернета через этот роутер.')+`<div class="split"><section class="surface"><div class="section-heading"><h2>Выход через другое устройство</h2><span class="pill">${nodes.length} доступно</span></div><div class="node-choice ${!selected?'selected':''}"><div><h3>Прямое подключение</h3><p>Не использовать другой Exit node</p></div><button data-exit="" ${!selected?'disabled':''}>${!selected?'Выбрано':'Выбрать'}</button></div>${nodes.map(n=>`<div class="node-choice ${n.ID===p.ExitNodeID?'selected':''}"><div><h3>${E(n.HostName)} ${n.ID===p.ExitNodeID?'<span class="pill">Текущий</span>':''}</h3><p>${goodBadge(n.Online)} · ${E(address(n))} · ${E(n.OS||'Устройство')}</p></div><button data-exit="${E(n.ID)}" ${!n.Online||n.ID===p.ExitNodeID?'disabled':''}>${n.ID===p.ExitNodeID?'Выбран':'Выбрать'}</button></div>`).join('')}${nodes.length?'':'<p class="empty">В сети пока нет одобренных Exit nodes. Сначала включите эту роль на одном из устройств и разрешите её в консоли сервера.</p>'}<form id="exit-options">${check('allow_lan','Доступ к своей LAN','Исключение для локальной сети при использовании внешнего Exit node. Не управляет объявлением подсетей.',p.ExitNodeAllowLANAccess)}<div class="form-actions"><button type="submit" ${!selected?'disabled':''}>Сохранить доступ к LAN</button></div></form></section><section class="surface"><h2>Этот роутер — Exit node</h2><p class="muted">Другие устройства смогут использовать интернет-подключение вашего роутера.</p><form id="advertise-form">${check('advertise_exit','Раздавать интернет в Tailscale','Объявить этот роутер как выходной узел.',s.exit_advertised)}<div class="note">После включения разрешите маршруты <code>0.0.0.0/0</code> и <code>::/0</code> в консоли Tailscale / Headscale.</div><div class="form-actions"><button type="submit" class="primary">Проверить и применить</button></div></form><div id="egress-section" class="egress-control"><h3>Через что раздавать интернет</h3><p class="muted">Получение политик подключений…</p></div><div class="keyline"></div><h3>Проверка выхода</h3><p class="muted small">HTTPS-запрос через интерфейс Tailscale без изменения настроек.</p><button data-diag="exit">Проверить выход</button></section></div>`}
function peersView(){const all=[{...data.tailscale.self,Online:data.tailscale.online,is_self:true},...data.tailscale.peers];const peers=all.filter(n=>[n.HostName,n.DNSName,...(n.TailscaleIPs||[]),data.devices?.[n.ID]?.notes].join(' ').toLowerCase().includes(query.toLowerCase()));return intro('Клиенты','Клиенты сети Tailscale, их веб-интерфейсы и ваши личные заметки.')+`<section class="surface"><div class="section-heading"><h2>Узлы сети <span class="pill">${all.length}</span></h2><input id="peer-search" class="search" type="search" aria-label="Найти клиента" placeholder="Имя, IP или заметка" value="${E(query)}"></div>${peerTable(peers)}<p class="device-help">«Панель» открывает управление этим роутером. «Веб» — адрес другого узла, обычно Tailscale :5252. Это ссылка, а не подтверждение доступности: нужен включённый веб-клиент и доступ через Tailscale. На Headscale 0.29.7 встроенный веб-клиент работает для просмотра сведений. Другой адрес и заметку можно задать в карточке.</p></section>`}
function routesView(){const p=data.tailscale.prefs;return intro('Подсети и DNS','Управление маршрутами клиента без перезаписи остальных параметров.')+`<div class="split"><section class="surface"><h2>Маршруты подсетей</h2><form id="routes-form"><label>Подсети за этим роутером<textarea name="routes" spellcheck="false" placeholder="192.168.10.0/24">${E((p.AdvertiseRoutes||[]).filter(x=>!x.endsWith('/0')).join('\n'))}</textarea></label><p class="muted small">По одной сети в строке. После объявления разрешите маршруты в консоли сервера.</p><button type="submit" class="primary">Проверить маршруты</button></form><div class="keyline"></div><form id="route-options">${check('accept_routes','Принимать маршруты других устройств','Использовать доступные подсети вашей сети Tailscale.',p.RouteAll)}${check('snat','SNAT для маршрутов подсетей','Подменять адрес источника при доступе из Tailscale в локальные сети.',!p.NoSNAT)}${check('stateful','Фильтрация перенаправленных соединений','Отслеживать состояния соединений между интерфейсами.',!p.NoStatefulFiltering)}<div class="form-actions"><button type="submit">Сохранить параметры</button></div></form></section><section class="surface"><h2>DNS и доступ</h2><form id="dns-form">${check('accept_dns','Принимать DNS с сервера','На Keenetic обычно выключено, чтобы сохранить штатный DNS роутера.',p.CorpDNS)}${check('shields_up','Блокировать входящие подключения','Узел останется в сети, но перестанет принимать входящие подключения от пиров.',p.ShieldsUp)}<div class="form-actions"><button type="submit">Сохранить DNS и доступ</button></div></form><div class="note">Настройки DHCP и DNS в самой KeeneticOS эта панель не заменяет.</div><div class="keyline"></div><h3>Объявленные другими узлами сети</h3>${pairs(data.tailscale.peers.filter(n=>n.PrimaryRoutes?.length).map(n=>[n.HostName,E(n.PrimaryRoutes.join(', '))]))}</section></div>`}
function nativeView(){const n=nativeData;if(!n)return intro('Подключение Keenetic','Подключение OpkgTun в штатном списке соединений роутера.')+'<section class="surface muted">Читаю настройки подключения…</section>';return intro('Подключение Keenetic','Создайте подключение Tailscale в интерфейсе Keenetic / Netcraze, как обычное интернет-соединение.')+`<div class="split"><section class="surface"><div class="section-heading"><h2>${E(n.name)}</h2><span class="status-badge ${n.exists?'good':'warn'}">${n.exists?'Подключение существует':'Не создано'}</span></div>${!n.available?`<div class="alert">${E(n.error)}</div>`:''}<form id="native-form"><label>Название подключения<input name="description" value="${E(n.description||'Tailscale')}" maxlength="50" ${n.exists?'disabled':''}></label><div class="form-grid"><label>Интерфейс<input value="${E(n.name)}" disabled></label><label>MTU<select name="mtu" ${n.exists?'disabled':''}>${[1280,1360,1420,1500].map(m=>`<option value="${m}" ${m==n.mtu?'selected':''}>${m}</option>`).join('')}</select></label></div>${check('global','Показывать как интернет-подключение','Позволяет выбрать соединение в политиках подключений роутера.',n.exists?n.global:true)}${check('save','Сохранить в конфигурацию роутера','Созданное подключение сохранится после перезагрузки.',true)}<div class="form-actions"><button class="primary" type="submit" ${!n.available?'disabled':''}>${n.exists?'Проверить существующее':'Создать подключение'}</button></div></form><div class="note">${n.exists?'Существующие параметры OpkgTun сохраняются. Повторная проверка не создаёт дубликат.':'Tailscale управляет адресами туннеля сам. Вручную задавать ему IP-адрес не нужно.'}</div></section><section class="surface"><h2>Связь с политиками</h2>${pairs([['Интерфейс Linux',E(n.tun||data.config.tun)],['Состояние',n.connected?'Подключён':'Не подключён'],['Создан панелью',n.managed?'Да':'Существующее подключение']])}<h3>Обнаруженные политики</h3>${(n.policies||[]).length?pairs(n.policies.map(p=>[p.name,'Таблица '+E(p.table)])):'<p class="muted small">Политик с этим подключением пока не обнаружено.</p>'}<div class="note">Назначение устройств и приоритеты соединений остаются в штатном веб-конфигураторе Keenetic. Панель сохраняет существующие политики.</div><a href="/" id="router-link" target="_blank" rel="noopener">Открыть панель роутера</a></section></div>`}
function diagnosticsView(){return intro('Диагностика','Проверки выполняются на роутере и не меняют его сетевые настройки.')+`
 <section class="surface"><div class="section-heading"><h2>Состояние панели и клиента</h2><div class="actions"><button id="check-health" class="primary">Проверить состояние</button><a href="/api/support-report" download>Скачать отчёт</a></div></div><p class="muted small">Версии компонентов, интерфейс, права доступа и место для обновлений. Отчёт не включает адреса, имена устройств, сервер управления, заметки, журналы и ключи.</p><div id="health-result" aria-live="polite"></div></section>
 <div class="split"><section class="surface"><h2>Проверки сети</h2><div class="node-choice"><div><h3>Соединение и DERP</h3><p>NAT, UDP и доступность серверов ретрансляции.</p></div><button data-diag="netcheck">Проверить</button></div><div class="node-choice"><div><h3>Выход в интернет</h3><p>HTTPS-запрос через ${E(data.config.tun)}.</p></div><button data-diag="exit">Проверить</button></div><div class="node-choice"><div><h3>Правила маршрутизации</h3><p>Просмотр действующих правил IPv4.</p></div><button data-diag="routes">Показать</button></div></section>
 <section class="surface"><h2>Проверка устройства</h2><form id="ping-form"><label>Устройство<select name="target">${data.tailscale.peers.map(n=>`<option value="${E(address(n))}">${E(n.HostName)} — ${E(address(n))}</option>`).join('')}</select></label><label>Тип проверки<select name="kind"><option value="ping">Соединение: direct / DERP</option><option value="tsmp">Туннель WireGuard: TSMP</option></select></label><button type="submit" class="primary" ${data.tailscale.peers.length?'':'disabled'}>Проверить устройство</button></form><div class="note">Первая проверка показывает путь к узлу. TSMP дополнительно проверяет обмен пакетами через WireGuard. Доступность отдельного приложения зависит от его настроек и ACL.</div><h3>Последние операции</h3><ul class="job-list">${jobRows()}</ul></section></div>`}
async function loadHealth(){
 const b=$('#check-health');b.disabled=true;
 try{const x=await api('/api/health'),root=$('#health-result');if(!root)return;root.innerHTML=`<div class="table-wrap"><table class="table"><thead><tr><th>Проверка</th><th>Результат</th></tr></thead><tbody>${x.checks.map(c=>`<tr><td>${E(c.label)}</td><td><span class="status-badge ${c.state==='ok'?'good':'warn'}">${c.state==='ok'?'В порядке':'Проверьте'}</span><p class="muted small">${E(c.detail)}</p></td></tr>`).join('')}</tbody></table></div><p class="muted small">CLI: ${E(x.versions.cli||'—')} · Демон: ${E(x.versions.daemon_file||'—')} · Работает: ${E(x.versions.running||'—')}<br>Память панели: ${x.resources.panel_rss_bytes===null?'—':bytes(x.resources.panel_rss_bytes)} · Потоков: ${E(x.resources.panel_threads??'—')} · Свободно: ${bytes(x.resources.free_bytes)}</p>`}
 catch(error){toast(error.message,true)}finally{b.disabled=false}
}
function logsView(){return intro('Журналы','События панели и доступные журналы клиента. Ключи и секреты скрываются.')+`<section class="surface"><div class="section-heading"><h2>События</h2><div class="actions"><select id="log-kind" aria-label="Выбрать журнал"><option value="panel">Панель</option><option value="client">Tailscale</option></select><button id="load-logs">Обновить</button></div></div><pre id="logs-output" class="console">Загрузка…</pre></section>`}
function backupsView(){return intro('Резервные копии','Сохранение настроек клиента без переноса секретного ключа устройства.',`<button class="primary" id="create-backup">Создать копию</button><button id="import-backup">Импортировать</button><input type="file" id="backup-file" accept="application/json,.json" hidden>`)+`<section class="surface"><h2>Сохранённые настройки</h2><div id="backup-list" class="muted">Загрузка…</div><div class="note">Копия содержит настройки клиента и подсетей. Выбор Exit node, его объявление и ключ устройства не восстанавливаются автоматически: они управляются отдельно.</div></section>`}
function systemView(){
 const p=data.tailscale.prefs;
 return intro('Клиент и панель','Отдельное обновление WebUI и клиента Tailscale. Установка выполняется после подтверждения.')+`
 <div class="split updates-grid">
  <section class="surface"><div class="section-heading"><h2>Клиент Tailscale</h2><span class="pill">${E(data.tailscale.version.split('-')[0])}</span></div><p class="muted small">Официальный стабильный ARM64-клиент. Проверка SHA256 и сохранение ключей устройства.</p><div id="update-info" class="note">Кнопка проверит версию и предложит установку, если есть обновление.</div><div class="actions"><button class="primary" id="check-update">Обновить клиент Tailscale</button></div></section>
  <section class="surface"><div class="section-heading"><h2>WebUI TailScaleKeen</h2><span class="pill">${E(data.panel_version)}</span></div><p class="muted small">Панель из GitHub Releases. Сохранение учётной записи, порта и настроек; откат при ошибке запуска.</p><div id="panel-update-info" class="note">Кнопка проверит версию и предложит установку, если есть обновление.</div><div class="actions"><button class="primary" id="check-panel-update">Обновить WebUI TailScaleKeen</button></div></section>
 </div><div class="keyline"></div><div class="split"><div class="stack">
 <section class="surface"><h2>Дополнительные параметры</h2><form id="advanced-form"><label>Имя устройства<input name="hostname" value="${E(p.Hostname||data.tailscale.self.HostName||'keenetic')}" maxlength="63"></label><label>Интеграция firewall<select name="netfilter">${['on','nodivert','off'].map(x=>`<option value="${x}" ${x===({0:'off',1:'nodivert',2:'on'}[p.NetfilterMode])?'selected':''}>${x}${x==='nodivert'?' — собственные правила Keenetic':''}</option>`).join('')}</select></label>${check('ssh','Tailscale SSH','Доступ по правилам SSH вашей сети; это отдельный SSH-сервер Tailscale.',p.RunSSH)}${check('webclient','Встроенный веб-клиент Tailscale','Просмотр сведений на порту 5252 через сеть Tailscale. Управление требует поддержки авторизации сервером.',p.RunWebClient)}<div class="form-actions"><button type="submit">Проверить параметры</button></div></form></section>
 <section class="surface"><h2>Управление панелью</h2>${pairs([['Вход',E(data.config.auth_source)],['Порт',E(data.config.port)],['Среда',E(data.system.architecture)+' / Entware']])}<p class="muted small"><a href="https://github.com/Zhanchuraev/TailScaleKeen" target="_blank" rel="noopener noreferrer">TailScaleKeen на GitHub</a></p><div class="keyline"></div><h3>Полное удаление</h3><p class="muted small">Удаление панели, клиента, его ключей и интеграции выполняется одной SSH-командой.</p><pre class="console">tailscalekeen uninstall --purge</pre><button id="purge-plan">Посмотреть список удаления</button><pre id="purge-output" hidden></pre></section></div>
 <div class="stack"><section class="surface"><h2>Подключение к сети</h2><form id="connect-form"><label>Сервер управления<input type="url" name="server" value="${E(p.ControlURL||'https://controlplane.tailscale.com')}" required></label><label>Имя устройства<input name="hostname" value="${E(p.Hostname||data.tailscale.self.HostName||'keenetic')}" required maxlength="63"></label><label>Ключ регистрации <span class="small">необязательно</span><input name="auth_key" type="password" autocomplete="off" placeholder="Оставьте пустым для входа в браузере"></label><p class="muted small">Для Headscale укажите URL своего сервера. Ключ передаётся клиенту через защищённый файл и сразу удаляется.</p><button type="submit" class="primary">Подключить</button></form>${authLink()}<div class="keyline"></div><button class="danger" data-action="logout">Выйти из сети Tailscale</button></section></div></div>`
}
const renderers={overview,exit:exitView,peers:peersView,routes:routesView,native:nativeView,diagnostics:diagnosticsView,logs:logsView,backups:backupsView,system:()=>systemView()+panelAccessView()};
async function render(){if(!data)return;page=location.hash.slice(1)||'overview';if(!pages[page])page='overview';$('#page-title').textContent=pages[page];$$('#nav a').forEach(a=>{a.classList.toggle('active',a.dataset.page===page);if(a.dataset.page===page)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});$('#main').className='page-'+page;$('#main').innerHTML=renderers[page]();decorateFields($('#main'));bindView();bindPanelAccess();if(page==='native'&&!nativeData){try{nativeData=await api('/api/native');if(page==='native')render()}catch(e){toast(e.message,true)}}if(page==='exit')loadEgress();if(page==='logs')loadLogs();if(page==='backups')loadBackups();if(page==='system')loadPanelSettings()}
async function refresh(manual=false){if(refreshBusy||credentialsBusy||!session.authenticated)return;refreshBusy=true;try{data=await api('/api/dashboard');status();if(manual){nativeData=null;await render();toast('Данные обновлены')}else if(['overview','peers'].includes(page)&&!$('#main form:focus-within')&&!$('#peer-search:focus')&&!$('#confirm').open)await render()}catch(e){$('#live-state').textContent='Нет ответа';$('#live-state').className='status-badge warn';if(manual)toast(e.message,true)}finally{refreshBusy=false}}
async function plan(action,params={}){try{pendingPlan=await api('/api/actions/plan',{action,params});$('#confirm-title').textContent='Проверка изменений';$('#confirm-description').textContent=pendingPlan.message;$('#confirm-changes').innerHTML=pendingPlan.changes.length?pendingPlan.changes.map(c=>`<div class="change-row"><strong>${E(labels[c.name]||c.name)}</strong><span class="before">${E(formatValue(c.before))}</span><span class="after">→ ${E(formatValue(c.after))}</span></div>`).join(''):'<div class="note">Изменений не требуется.</div>';$('#confirm-commands').textContent=pendingPlan.commands.map(x=>Array.isArray(x)?x.join(' '):x).join('\n');$('#command-details').hidden=!pendingPlan.commands.length;$('#confirm-apply').textContent=pendingPlan.changes.length?'Применить':'Подтвердить проверку';$('#confirm').showModal()}catch(e){toast(e.message,true)}}
function formatValue(x){return Array.isArray(x)?x.join(', ')||'Нет':typeof x==='boolean'?x?'Включено':'Выключено':x??'Нет'}
async function showJob(id){activeJob=id;$('#job-dialog').showModal();await pollJob()}
async function pollJob(){if(!activeJob)return;try{const j=await api('/api/jobs/'+activeJob);$('#job-title').textContent=j.label;$('#job-state').textContent={running:'Выполняется',done:'Готово',error:'Ошибка',interrupted:'Прервано'}[j.state]||j.state;$('#job-state').className='status-badge '+(j.state==='done'?'good':j.state==='error'?'bad':'warn');$('#job-output').textContent=(j.log||[]).map(x=>new Date(x.at*1000).toLocaleTimeString('ru-RU')+'  '+x.text).join('\n')||'Подготовка…';$('#job-result').textContent=j.error||j.result?.message||'';if(j.result?.auth_url&&/^https:\/\//.test(j.result.auth_url)){const a=document.createElement('a');a.href=j.result.auth_url;a.target='_blank';a.rel='noopener noreferrer';a.textContent='Открыть страницу регистрации';$('#job-result').append(document.createElement('br'),a)}if(j.result?.panel_update){activeJob=null;localStorage.setItem('tailscalekeen-update',JSON.stringify({version:j.result.version,at:Date.now()}));watchPanelUpdate();return}if(j.state==='running')setTimeout(pollJob,1200);else{activeJob=null;await refresh(false);await render()}}catch(e){toast(e.message,true);activeJob=null}}
function fields(form,names){const r={};for(const n of names){const x=form.elements[n];r[n]=x.type==='checkbox'?x.checked:x.value}return r}
function bindView(){const root=$('#main');$$('[data-copy-address]',root).forEach(b=>b.onclick=()=>copyAddress(b.dataset.copyAddress,b));$$('[data-action]',root).forEach(b=>b.onclick=()=>plan(b.dataset.action));$$('[data-exit]',root).forEach(b=>b.onclick=()=>plan('settings',{exit_node:b.dataset.exit}));$$('[data-diag]',root).forEach(b=>b.onclick=()=>diagnose(b.dataset.diag));$$('[data-ping]',root).forEach(b=>b.onclick=()=>diagnose('ping',b.dataset.ping));$$('[data-job]',root).forEach(b=>b.onclick=()=>showJob(b.dataset.job));$$('[data-device]',root).forEach(b=>b.onclick=()=>openDevice(b.dataset.device));
const forms={'exit-options':['allow_lan'],'advertise-form':['advertise_exit'],'route-options':['accept_routes','snat','stateful'],'dns-form':['accept_dns','shields_up'],'advanced-form':['hostname','netfilter','ssh','webclient']};for(const [id,names] of Object.entries(forms)){const form=$('#'+id);if(form)form.onsubmit=e=>{e.preventDefault();plan('settings',fields(form,names))}}
if($('#routes-form'))$('#routes-form').onsubmit=e=>{e.preventDefault();plan('settings',{routes:e.target.elements.routes.value.split(/[\n,]+/).map(x=>x.trim()).filter(Boolean)})};
if($('#native-form')){if(nativeData.exists){$('#native-form').elements.global.disabled=true;$('#native-form').elements.save.disabled=true;}$('#native-form').onsubmit=e=>{e.preventDefault();const f=e.target;plan('native_create',nativeData.exists?{}:{description:f.elements.description.value,mtu:Number(f.elements.mtu.value),global:f.elements.global.checked,save:f.elements.save.checked})};const u=new URL(location.href);u.port='';u.pathname='/';u.hash='';u.search='';$('#router-link').href=u.href}
if($('#ping-form'))$('#ping-form').onsubmit=e=>{e.preventDefault();diagnose(e.target.elements.kind.value,e.target.elements.target.value)};
if($('#connect-form'))$('#connect-form').onsubmit=e=>{e.preventDefault();const f=e.target,params=fields(f,['server','hostname','auth_key']);plan('connect',params);f.elements.auth_key.value=''};
if($('#peer-search'))$('#peer-search').oninput=e=>{query=e.target.value;const cursor=e.target.selectionStart;$('#main').innerHTML=peersView();bindView();$('#peer-search').focus();$('#peer-search').setSelectionRange(cursor,cursor)};
if($('#load-logs')){$('#load-logs').onclick=loadLogs;$('#log-kind').onchange=loadLogs}
if($('#create-backup')){$('#create-backup').onclick=async()=>{try{await api('/api/backups',{});await loadBackups();toast('Настройки сохранены')}catch(e){toast(e.message,true)}};$('#import-backup').onclick=()=>$('#backup-file').click();$('#backup-file').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>1024*1024)throw Error('Файл слишком большой');await api('/api/backups/import',{backup:JSON.parse(await file.text())});await loadBackups();toast('Копия импортирована. Для применения выберите «Восстановить».')}catch(e){toast(e.message,true)}}}
if($('#check-health'))$('#check-health').onclick=loadHealth;
if($('#check-panel-update')){$('#check-panel-update').onclick=checkPanelUpdate;loadPanelUpdateStatus()}
if($('#check-update')){$('#check-update').onclick=checkUpdate;$('#purge-plan').onclick=async()=>{try{const p=await api('/api/uninstall-plan');$('#purge-output').hidden=false;$('#purge-output').textContent=JSON.stringify(p,null,2)}catch(e){toast(e.message,true)}}}}
async function diagnose(kind,target=''){try{const j=await api('/api/diagnostics',{kind,target});await showJob(j.id)}catch(e){toast(e.message,true)}}
async function loadLogs(){try{const d=await api('/api/logs?kind='+encodeURIComponent($('#log-kind')?.value||'panel'));if($('#logs-output'))$('#logs-output').textContent=d.map(x=>x.name+'\n'+x.text).join('\n\n')}catch(e){toast(e.message,true)}}
async function loadBackups(){try{const list=await api('/api/backups');const root=$('#backup-list');if(!root)return;root.innerHTML=list.length?`<table class="table"><thead><tr><th>Создана</th><th>Копия настроек</th><th>Действия</th></tr></thead><tbody>${list.map(b=>`<tr><td>${E(date(b.created_at))}</td><td>${E(b.settings.hostname||'Настройки клиента')}</td><td><div class="actions"><a href="/api/backups/${E(b.id)}" download>Скачать</a><button class="text-link" data-restore="${E(b.id)}">Восстановить</button><button class="text-link" data-delete="${E(b.id)}">Удалить</button></div></td></tr>`).join('')}</tbody></table>`:'<div class="empty">Сохранённых копий пока нет.</div>';$$('[data-restore]',root).forEach(b=>b.onclick=()=>plan('restore',{backup:b.dataset.restore}));$$('[data-delete]',root).forEach(b=>b.onclick=async()=>{if(!window.confirm('Удалить выбранную копию настроек?'))return;try{await api('/api/backups/delete',{backup:b.dataset.delete});await loadBackups()}catch(e){toast(e.message,true)}})}catch(e){toast(e.message,true)}}
async function checkUpdate(){const b=$('#check-update');b.disabled=true;$('#update-info').textContent='Проверяю официальный каталог…';try{const x=await api('/api/updates');$('#update-info').textContent=x.available?`Доступно обновление или восстановление клиента до ${x.latest}.`:`Установлен актуальный стабильный клиент ${x.current}.`;if(x.available)await plan('update_client')}catch(e){$('#update-info').textContent=e.message;toast(e.message,true)}finally{b.disabled=false}}
function showLogin(){session.authenticated=false;$('#app').hidden=true;$('#login-screen').hidden=false}
let booting=null;
function boot(){if(booting)return booting;booting=loadSession().finally(()=>{booting=null});return booting}
async function loadSession(){try{session=await api('/api/session');if(session.authenticated){$('#login-screen').hidden=true;$('#app').hidden=false;data=await api('/api/dashboard');status();await render();const trial=new URLSearchParams(location.hash.slice(1)).get('port-confirm');if(trial)await showPortTrial(trial)}else{showLogin();const first=!session.configured,f=$('#login-form');$('#password-confirm-label').hidden=!first;f.elements.password_confirm.required=first;f.elements.password.minLength=first?6:0;f.elements.password.autocomplete=first?'new-password':'current-password';f.elements.username.autocomplete=first?'off':'username';if(first){f.reset();f.elements.username.value='';f.elements.password.value='';f.elements.password_confirm.value=''}$('#login-title').textContent=first?'Создание учётной записи':'Вход в панель Tailscale';$('#login-description').textContent=first?'Задайте отдельные логин и пароль для TailScaleKeen.':'Войдите в панель управления Tailscale.';$('#login-form button[type=submit]').textContent=first?'Создать учётную запись':'Войти';$('#login-hint').textContent=first?'Задайте логин и дважды введите пароль — от 6 знаков, в том числе только цифры.':'Забыли пароль? В SSH выполните: tailscalekeen reset-password'}}catch(e){showLogin();$('#login-error').textContent=e.message}}
$('#login-form').onsubmit=async e=>{e.preventDefault();const b=$('#login-form button[type=submit]');b.disabled=true;$('#login-error').textContent='';try{const f=e.target;if(!session.configured&&f.elements.password.value!==f.elements.password_confirm.value)throw Error('Пароли не совпадают.');const r=await api(session.configured?'/api/login':'/api/setup',fields(f,session.configured?['username','password']:['username','password','password_confirm']));session={...session,...r,configured:true};f.reset();await boot()}catch(e){$('#login-error').textContent=e.message}finally{b.disabled=false}};
$('#logout').onclick=async()=>{try{await api('/api/logout',{});$('#appearance').close();await boot()}catch(e){toast(e.message,true)}};
$('#confirm-apply').onclick=async()=>{const b=$('#confirm-apply');b.disabled=true;try{const j=await api('/api/actions/apply',{plan_id:pendingPlan.id});pendingPlan=null;$('#confirm').close();await showJob(j.id)}catch(e){toast(e.message,true)}finally{b.disabled=false}};
$('#confirm').addEventListener('close',()=>{const old=pendingPlan;pendingPlan=null;if(old)api('/api/actions/cancel',{plan_id:old.id}).catch(error=>toast(error.message,true))});
$('#job-close').onclick=()=>{$('#job-dialog').close();activeJob=null};
$('#refresh').onclick=()=>refresh(true);
function mobileMenu(open){$('.sidebar').classList.toggle('open',open);$('#menu').setAttribute('aria-expanded',String(open));$('#menu-scrim').hidden=!open}
$('#menu').onclick=()=>mobileMenu(!$('.sidebar').classList.contains('open'));$('#menu-scrim').onclick=()=>mobileMenu(false);
document.addEventListener('keydown',e=>{if(e.key==='Escape')mobileMenu(false)});
const preferredTheme=matchMedia('(prefers-color-scheme: dark)');
function applyTheme(mode){if(!['auto','light','dark'].includes(mode))mode='auto';document.documentElement.dataset.theme=mode==='auto'?(preferredTheme.matches?'dark':'light'):mode;$('#theme-mode').value=mode;localStorage.setItem('ts-panel-theme',mode)}
applyTheme(localStorage.getItem('ts-panel-theme')||'auto');preferredTheme.addEventListener('change',()=>{if($('#theme-mode').value==='auto')applyTheme('auto')});
$('#theme-mode').onchange=e=>applyTheme(e.target.value);$('#theme').onclick=()=>$('#appearance').showModal();$('#appearance-close').onclick=()=>$('#appearance').close();$('#settings-system-link').onclick=()=>$('#appearance').close();
$('#native-web-link').href=location.protocol+'//'+location.hostname+'/';
function collapseMenu(collapsed){document.documentElement.classList.toggle('menu-collapsed',collapsed);$('#collapse-menu').setAttribute('aria-expanded',String(!collapsed));$('#collapse-menu').setAttribute('aria-label',collapsed?'Показывать меню':'Скрывать меню');localStorage.setItem('ts-panel-menu-collapsed',String(collapsed))}
collapseMenu(localStorage.getItem('ts-panel-menu-collapsed')==='true');$('#collapse-menu').onclick=()=>collapseMenu(!document.documentElement.classList.contains('menu-collapsed'));
$$('.nav-group-title').forEach(title=>{title.title=title.textContent.trim();title.tabIndex=0;title.setAttribute('role','button');const open=()=>{if(document.documentElement.classList.contains('menu-collapsed'))collapseMenu(false)};title.onclick=open;title.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();open()}}});
window.addEventListener('hashchange',()=>{mobileMenu(false);render()});setInterval(()=>{if(!document.hidden)refresh(false)},5000);boot();

function icon(name){const paths={copy:'<rect x="8" y="6" width="12" height="16" rx="1"/><path d="M16 3H4v15"/>',wifi:'<path d="M2 8a16 16 0 0 1 20 0M5 12a11 11 0 0 1 14 0M8 16a6 6 0 0 1 8 0"/><circle cx="12" cy="20" r="1" fill="currentColor" stroke="none"/>',monitor:'<rect x="3" y="3" width="7" height="7"/><rect x="14" y="3" width="7" height="7"/><rect x="3" y="14" width="7" height="7"/><rect x="14" y="14" width="7" height="7"/>',globe:'<circle cx="12" cy="12" r="9"/><ellipse cx="12" cy="12" rx="4" ry="9"/><path d="M3 12h18M5 6.5h14M5 17.5h14"/>',devices:'<rect x="2" y="4" width="14" height="10" rx="1"/><path d="M7 14v5M4 19h10"/><rect x="18" y="8" width="4" height="12" rx="1"/>',shield:'<path d="M12 2 21 6v6c0 5-5 8-9 10-4-2-9-5-9-10V6Z"/>',settings:'<path d="m9 3-.7 2.3-2 .9-2.2-.5-2 3.5 1.6 1.8v2.2L2.1 15l2 3.5 2.2-.5 2 .9L9 21h4l.7-2.1 2-.9 2.2.5 2-3.5-1.6-1.8V11l1.6-1.8-2-3.5-2.2.5-2-.9L13 3Z"/><circle cx="11" cy="12" r="3"/>',external:'<path d="M14 3h7v7M21 3l-11 11M10 4H4v16h16v-6"/>',edit:'<path d="m15 4 5 5-11 11H4v-5ZM13 6l5 5"/>',pulse:'<path d="M2 15h5l3-10 4 15 3-9 2 4h3"/>',refresh:'<path d="M20 10a8 8 0 1 0 0 6M20 3v7h-7"/>',theme:'<circle cx="12" cy="12" r="9"/><path d="M12 3v18"/>',menu:'<path d="M3 6h18M3 12h18M3 18h18"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',arrow:'<path d="m12 5-7 7 7 7M5 12h15"/>',eye:'<path d="M2 12s3-7 10-7 10 7 10 7-3 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/>',route:'<circle cx="5" cy="5" r="2"/><circle cx="19" cy="19" r="2"/><path d="M5 7v9a3 3 0 0 0 3 3h9M19 17V8a3 3 0 0 0-3-3H7"/>'};return `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${paths[name]||paths.globe}</svg>`}
async function loadEgress(){try{const value=await api('/api/egress');const root=$('#egress-section');if(!root)return;root.innerHTML=`<h3>Через что раздавать интернет</h3><p class="muted small">Выход для устройств, которые выбрали этот роутер как Exit node.</p><form id="egress-form"><label>Подключение или политика<select name="target" aria-label="Выход для клиентов Exit node">${value.choices.map(x=>`<option value="${E(x.id)}" ${x.id===value.current.target?'selected':''} ${!x.available?'disabled':''}>${E(x.label)}${x.available?'':' — нет подключения'}</option>`).join('')}</select></label><p class="egress-status">Сейчас: ${E(value.current.label)}.</p><div class="form-actions"><button type="submit" class="primary">Проверить и применить</button></div></form><div class="note">LAN и связь между устройствами Tailscale сохраняются. VPN выбирается через его политику Keenetic. При отказе выбранного выхода другой провайдер не используется. IPv6 без рабочего выхода блокируется.</div>`;decorateFields(root);$('#egress-form').onsubmit=e=>{e.preventDefault();plan('egress',{target:e.target.elements.target.value})}}catch(e){if($('#egress-section'))$('#egress-section').textContent=e.message}}
function openDevice(id){const peer=[data.tailscale.self,...data.tailscale.peers].find(n=>String(n.ID)===id);const card=data.devices?.[id];if(!peer||!card)return;activeDevice={id,revision:card.revision};$('#device-title').textContent=peer.HostName||peer.DNSName||'Устройство';$('#device-addresses').textContent=(peer.TailscaleIPs||[]).join(' · ');const f=$('#device-form');f.elements.notes.value=card.notes||'';f.elements.url.value=card.custom_url||'';f.elements.url.placeholder=card.url||'';$('#device-open').href=deviceURL({...peer,is_self:String(data.tailscale.self.ID)===id},card);$('#device-open').hidden=!$('#device-open').getAttribute('href');$('#device-dialog').showModal()}
$('#device-form').onsubmit=async e=>{e.preventDefault();if(!activeDevice)return;const f=e.target,b=f.querySelector('[type=submit]');b.disabled=true;try{const card=await api('/api/devices',{...activeDevice,notes:f.elements.notes.value,url:f.elements.url.value.trim()});data.devices[activeDevice.id]=card;$('#device-dialog').close();await render();toast('Карточка устройства сохранена')}catch(err){toast(err.message,true)}finally{b.disabled=false}};
$('#device-close').onclick=()=>$('#device-dialog').close();
$('#refresh').innerHTML=icon('refresh');$('#theme').innerHTML=icon('settings');$('#menu').innerHTML=icon('menu');$$('[data-nav-icon]').forEach(e=>e.innerHTML=icon(e.dataset.navIcon));

function deviceURL(peer,card){return peer.is_self&&!card.custom_url?location.origin+'/':card.url||''}
function decorateFields(root){
 $$('label',root).forEach(label=>{if(label.classList.contains('outlined-field')||label.classList.contains('check-row'))return;const input=[...label.children].find(e=>e.matches('input:not([type=checkbox]),select,textarea'));if(!input)return;const caption=document.createElement('span');caption.className='field-caption';[...label.childNodes].filter(n=>n!==input&&!(n.nodeType===1&&n.matches('button'))).forEach(n=>caption.append(n));label.prepend(caption);label.classList.add('outlined-field')});
 $$('input[type=checkbox]',root).forEach(input=>input.setAttribute('role','switch'));
}
decorateFields(document);
$$('[data-ui-icon]').forEach(e=>e.innerHTML=icon(e.dataset.uiIcon));
$$('.dialog-head .icon-button').forEach(e=>e.innerHTML=icon('close'));
$('#show-password').innerHTML=icon('eye');$('#show-password').onclick=()=>{const input=$('#login-form [name=password]'),show=input.type==='password';input.type=show?'text':'password';$('#show-password').setAttribute('aria-pressed',String(show));$('#show-password').setAttribute('aria-label',show?'Скрыть пароль':'Показать пароль')};

function panelAccessView(){return `<div class="keyline"></div><div class="split"><section class="surface"><h2>Учётная запись панели</h2><p class="muted small">Отдельные логин и пароль TailScaleKeen. После сохранения другие сеансы будут завершены.</p><form id="account-form"><label>Логин<input name="username" autocomplete="username" required maxlength="64" value="${E(session.user||'')}"></label><label>Текущий пароль<input name="current_password" type="password" autocomplete="current-password" required maxlength="256"></label><label>Новый пароль<input name="password" type="password" autocomplete="new-password" required minlength="6" maxlength="256"></label><label>Повторите новый пароль<input name="password_confirm" type="password" autocomplete="new-password" required minlength="6" maxlength="256"></label><p id="account-error" class="error" role="alert"></p><button type="submit" class="primary">Сохранить учётную запись</button></form><p class="muted small recovery-hint">Если пароль забыт, в SSH: <code>tailscalekeen reset-password</code></p></section><section class="surface"><h2>Доступ к панели</h2><form id="panel-port-form"><label>Порт панели<input name="port" type="number" min="1024" max="65535" step="1" required value="${E(data.config.port)}"></label><p class="muted small">Откройте новый адрес и подтвердите, что панель работает. До подтверждения прежний адрес остаётся доступным. Через две минуты неподтверждённое изменение отменяется.</p><p id="panel-port-error" class="error" role="alert"></p><button type="submit">Изменить порт</button></form><p id="panel-port-status" class="muted small recovery-hint"></p></section></div>`}
function bindPanelAccess(){
 const form=$('#account-form');if(form)form.onsubmit=async e=>{e.preventDefault();const b=form.querySelector('[type=submit]');$('#account-error').textContent='';try{if(form.elements.password.value!==form.elements.password_confirm.value)throw Error('Пароли не совпадают.');b.disabled=true;credentialsBusy=true;while(refreshBusy)await new Promise(resolve=>setTimeout(resolve,25));const result=await api('/api/password',fields(form,['username','current_password','password','password_confirm']));form.reset();session={...session,...result};await boot();toast('Учётная запись сохранена. Другие сеансы завершены.')}catch(e){if($('#account-error'))$('#account-error').textContent=e.message}finally{credentialsBusy=false;b.disabled=false}};
 const port=$('#panel-port-form');if(port)port.onsubmit=async e=>{e.preventDefault();if(credentialsBusy){toast('Дождитесь сохранения учётной записи.');return}$('#panel-port-error').textContent='';const b=port.querySelector('button');b.disabled=true;try{const value=await api('/api/panel-port/begin',{port:Number(port.elements.port.value)});if(value.unchanged){toast('Этот порт уже используется');return}await showPortTrial(value.id)}catch(e){$('#panel-port-error').textContent=e.message}finally{b.disabled=false}}
}
async function loadPanelSettings(){try{const settings=await api('/api/panel-settings');if($('#panel-port-status'))$('#panel-port-status').textContent=settings.pending?'Проверяется порт '+settings.pending.new_port+'. Прежний порт '+settings.pending.old_port+' пока доступен.':'Текущий порт: '+settings.port+'.';if($('#account-form'))$('#account-form').elements.username.value=settings.username}catch(e){toast(e.message,true)}}
let portTrial=null;
function portURL(port,hash){const u=new URL(location.href);u.port=String(port);u.pathname='/';u.search='';u.hash=hash;return u.href}
async function showPortTrial(id){const settings=await api('/api/panel-settings'),p=settings.pending;if(!p||p.id!==id){toast('Проверка порта уже завершена. Используйте прежний адрес, если изменение не было подтверждено.',true);return}portTrial=p;const atNew=Number(location.port||(location.protocol==='https:'?443:80))===p.new_port;$('#port-message').textContent=atNew?'Новый адрес открылся. Подтвердите смену порта до '+new Date(p.expires_at*1000).toLocaleTimeString('ru-RU')+'.':'Откройте новый адрес и подтвердите смену. До '+new Date(p.expires_at*1000).toLocaleTimeString('ru-RU')+' прежний адрес остаётся доступным.';$('#port-old-link').href=portURL(p.old_port,'system');$('#port-old-link').textContent=$('#port-old-link').href;$('#port-new-link').href=portURL(p.new_port,'port-confirm='+p.id);$('#port-new-link').hidden=atNew;$('#port-confirm').hidden=!atNew;$('#port-error').textContent='';if(!$('#port-dialog').open)$('#port-dialog').showModal()}
$('#port-confirm').onclick=async()=>{try{await api('/api/panel-port/confirm',{id:portTrial.id});$('#port-dialog').close();location.hash='system';await boot();toast('Новый порт сохранён')}catch(e){$('#port-error').textContent=e.message}};
$('#port-cancel').onclick=async()=>{try{const result=await api('/api/panel-port/cancel',{});location.href=portURL(result.port,'system')}catch(e){$('#port-error').textContent=e.message}};
$('#port-dialog-close').onclick=()=>$('#port-dialog').close();

async function checkPanelUpdate(){
 const button=$('#check-panel-update');button.disabled=true;$('#panel-update-info').textContent='Проверяю стабильные релизы GitHub…';
 try{const info=await api('/api/panel-updates?fresh=1');$('#panel-update-info').textContent=info.available?`Установлена ${info.current}. Доступна ${info.latest}.`:`Установлена актуальная панель ${info.current}.`;if(info.available)await plan('update_panel')}
 catch(error){$('#panel-update-info').textContent=error.message;toast(error.message,true)}finally{button.disabled=false}
}
async function loadPanelUpdateStatus(){
 try{const result=await api('/api/panel-update-status');if(result.state&&$('#panel-update-info'))$('#panel-update-info').textContent=result.message;if(['prepared','installing','checking'].includes(result.state)){localStorage.setItem('tailscalekeen-update',JSON.stringify({version:result.version,at:Date.now()}));watchPanelUpdate()}}catch(error){toast(error.message,true)}
}
let panelUpdateWatching=false;
async function watchPanelUpdate(){
 if(panelUpdateWatching)return;panelUpdateWatching=true;
 let pending;try{pending=JSON.parse(localStorage.getItem('tailscalekeen-update')||'null')}catch{localStorage.removeItem('tailscalekeen-update')}
 if(!pending||Date.now()-pending.at>600000){localStorage.removeItem('tailscalekeen-update');panelUpdateWatching=false;return}
 const until=Date.now()+120000;
 while(Date.now()<until){
  if($('#job-state'))$('#job-state').textContent='Обновляется панель';
  if($('#job-result'))$('#job-result').textContent='Дождитесь завершения. Соединение с панелью временно прервётся.';
  try{
   const response=await fetch('/api/session',{credentials:'same-origin',cache:'no-store',signal:AbortSignal.timeout(4000)}),value=await response.json(),result=value.panel_update;
   if(result&&['done','rolled_back','error'].includes(result.state)){
    localStorage.removeItem('tailscalekeen-update');panelUpdateWatching=false;$('#job-dialog').close();await boot();toast(result.message,result.state!=='done');return
   }
  }catch{}
  await new Promise(resolve=>setTimeout(resolve,1800));
 }
 panelUpdateWatching=false;toast('Проверка обновления продолжается. Обновите страницу и войдите снова; результат сохранён в разделе «Клиент и панель».',true)
}
if(localStorage.getItem('tailscalekeen-update'))watchPanelUpdate();
